namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Room { get; set; } = "";
    public bool IsFeatured { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = "";
    public Instructor Instructor { get; set; } = new();
}

namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public int CourseCount { get; set; }
}

namespace CourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Email { get; set; } = "";
    public string Bio { get; set; } = "";
    public string OfficeHours { get; set; } = "";
    public string Office { get; set; } = "";
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]{6,12}$", ErrorMessage = "Student ID must be 6–12 alphanumeric characters.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Instructor> _instructors;
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Email = "achen@university.edu", Bio = "Dr. Chen specializes in distributed systems and cloud computing. She has published over 40 peer-reviewed papers and received the University Teaching Excellence Award in 2024.", OfficeHours = "Mon/Wed 2–4 PM", Office = "CS Building 312" },
            new() { Id = 2, Name = "Dr. Robert Okafor", Title = "Associate Professor of Mathematics", Email = "rokafor@university.edu", Bio = "Dr. Okafor's research focuses on applied mathematics and statistical modeling. He previously worked at NASA's Jet Propulsion Laboratory.", OfficeHours = "Tue/Thu 10 AM–12 PM", Office = "Math Hall 205" },
            new() { Id = 3, Name = "Prof. Maria Santos", Title = "Professor of English Literature", Email = "msantos@university.edu", Bio = "Prof. Santos is a specialist in 19th-century American literature and creative writing. She is the author of three novels and a collection of short stories.", OfficeHours = "Mon/Fri 1–3 PM", Office = "Humanities 418" },
            new() { Id = 4, Name = "Dr. James Whitfield", Title = "Assistant Professor of Physics", Email = "jwhitfield@university.edu", Bio = "Dr. Whitfield researches quantum mechanics and condensed matter physics. He completed his postdoctoral fellowship at CERN.", OfficeHours = "Wed/Fri 11 AM–1 PM", Office = "Science Center 102" },
            new() { Id = 5, Name = "Dr. Priya Sharma", Title = "Professor of History", Email = "psharma@university.edu", Bio = "Dr. Sharma is an expert in modern Asian history and global migration studies. She has directed the University's Asian Studies Program since 2020.", OfficeHours = "Tue/Thu 3–5 PM", Office = "Liberal Arts 310" },
            new() { Id = 6, Name = "Dr. Emily Park", Title = "Associate Professor of Biology", Email = "epark@university.edu", Bio = "Dr. Park studies molecular biology and genetics with a focus on CRISPR applications. She leads the university's Genomics Research Lab.", OfficeHours = "Mon/Wed 9–11 AM", Office = "Life Sciences 220" },
        };

        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS" },
            new() { Id = 2, Name = "Mathematics", Code = "MATH" },
            new() { Id = 3, Name = "English", Code = "ENG" },
            new() { Id = 4, Name = "Physics", Code = "PHYS" },
            new() { Id = 5, Name = "History", Code = "HIST" },
            new() { Id = 6, Name = "Biology", Code = "BIO" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, data structures, object-oriented design, and basic algorithms. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "CS Building 101", IsFeatured = true, DepartmentId = 1, DepartmentName = "Computer Science", Instructor = _instructors[0] },
            new() { Id = 2, CourseCode = "CS 301", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms). Includes complexity analysis and practical implementation projects.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Room = "CS Building 203", IsFeatured = true, DepartmentId = 1, DepartmentName = "Computer Science", Instructor = _instructors[0] },
            new() { Id = 3, CourseCode = "CS 450", Title = "Cloud Computing", Description = "Explore modern cloud architectures, containerization, serverless computing, and DevOps practices. Hands-on projects using major cloud platforms.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Room = "CS Building 305", IsFeatured = false, DepartmentId = 1, DepartmentName = "Computer Science", Instructor = _instructors[0] },
            new() { Id = 4, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues and eigenvectors. Applications to computer graphics, data science, and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Math Hall 110", IsFeatured = true, DepartmentId = 2, DepartmentName = "Mathematics", Instructor = _instructors[1] },
            new() { Id = 5, CourseCode = "MATH 310", Title = "Probability & Statistics", Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, regression, and Bayesian inference. Emphasizes real-world data analysis.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Room = "Math Hall 215", IsFeatured = false, DepartmentId = 2, DepartmentName = "Mathematics", Instructor = _instructors[1] },
            new() { Id = 6, CourseCode = "ENG 110", Title = "Academic Writing", Description = "Develop college-level writing skills through essay composition, research methods, argumentation, and revision strategies. Focuses on clarity, structure, and critical thinking.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:15 PM", Room = "Humanities 201", IsFeatured = false, DepartmentId = 3, DepartmentName = "English", Instructor = _instructors[2] },
            new() { Id = 7, CourseCode = "ENG 340", Title = "American Literature: 1850–1920", Description = "A survey of American literature from the pre-Civil War period through the Gilded Age. Authors include Melville, Dickinson, Twain, and Wharton.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", Room = "Humanities 305", IsFeatured = true, DepartmentId = 3, DepartmentName = "English", Instructor = _instructors[2] },
            new() { Id = 8, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Covers Newton's laws, energy conservation, rotational motion, and introductory fluid mechanics. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Room = "Science Center 150", IsFeatured = false, DepartmentId = 4, DepartmentName = "Physics", Instructor = _instructors[3] },
            new() { Id = 9, CourseCode = "PHYS 320", Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, quantum states, measurement theory, and applications to atomic and molecular systems.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Room = "Science Center 210", IsFeatured = true, DepartmentId = 4, DepartmentName = "Physics", Instructor = _instructors[3] },
            new() { Id = 10, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations from antiquity through the late medieval period. Covers Mesopotamia, Greece, Rome, China, the Islamic Golden Age, and sub-Saharan Africa.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", Room = "Liberal Arts 120", IsFeatured = false, DepartmentId = 5, DepartmentName = "History", Instructor = _instructors[4] },
            new() { Id = 11, CourseCode = "HIST 415", Title = "Modern Asia: 1800–Present", Description = "Political, economic, and cultural transformations in East and South Asia. Topics include colonialism, independence movements, the Cold War in Asia, and contemporary geopolitics.", Credits = 3, Schedule = "Thu 6:00–8:45 PM", Room = "Liberal Arts 310", IsFeatured = false, DepartmentId = 5, DepartmentName = "History", Instructor = _instructors[4] },
            new() { Id = 12, CourseCode = "BIO 150", Title = "Introduction to Biology", Description = "Foundational concepts in cell biology, genetics, evolution, and ecology. Includes laboratory work with microscopy, DNA extraction, and ecological field studies.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Life Sciences 105", IsFeatured = true, DepartmentId = 6, DepartmentName = "Biology", Instructor = _instructors[5] },
            new() { Id = 13, CourseCode = "BIO 360", Title = "Molecular Genetics", Description = "Gene structure and regulation, DNA replication, transcription, translation, and recombinant DNA technology. Includes a semester-long CRISPR research project.", Credits = 4, Schedule = "Tue/Thu 1:00–2:50 PM", Room = "Life Sciences 320", IsFeatured = false, DepartmentId = 6, DepartmentName = "Biology", Instructor = _instructors[5] },
        };

        foreach (var dept in _departments)
        {
            dept.CourseCount = _courses.Count(c => c.DepartmentId == dept.Id);
        }
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.CourseCode).ToList();
    }

    public List<Course> GetAllCourses() => _courses.OrderBy(c => c.CourseCode).ToList();
}

