arguments.file_text:
@page "/"

<PageTitle>University Course Catalog</PageTitle>

<div class="container py-4">
    <div class="text-center mb-5">
        <h1 class="display-4">University Course Catalog</h1>
        <p class="lead text-muted">Browse departments, explore courses, and submit your enrollment request.</p>
        <a href="/courses" class="btn btn-primary btn-lg mt-2">Browse All Courses</a>
    </div>

    <section class="mb-5">
        <h2 class="mb-3">Departments</h2>
        <div class="row g-3">
            @foreach (var dept in Departments)
            {
                <div class="col-md-4 col-sm-6" @key="dept.Id">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@dept.Name</h5>
                            <p class="card-text text-muted">@dept.CourseCount course(s)</p>
                            <a href="/courses?dept=@dept.Id" class="btn btn-outline-primary btn-sm">View Courses</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>

    <section>
        <h2 class="mb-3">Featured Courses</h2>
        <div class="row g-3">
            @foreach (var course in FeaturedCourses)
            {
                <div class="col-md-6" @key="course.Id">
                    <div class="card h-100 border-primary">
                        <div class="card-body">
                            <span class="badge bg-primary mb-2">Featured</span>
                            <h5 class="card-title">@course.CourseCode — @course.Title</h5>
                            <p class="card-text">@course.Credits credits · @course.Instructor.Name</p>
                            <p class="card-text text-muted">@Truncate(course.Description, 120)</p>
                            <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>
</div>

@code {
    [Inject] public CatalogService Catalog { get; set; } = default!;

    private List<Department> Departments { get; set; } = [];
    private List<Course> FeaturedCourses { get; set; } = [];

    protected override void OnInitialized()
    {
