@page "/courses"
@rendermode InteractiveServer
@using CourseCatalog.Models
@using CourseCatalog.Services

<PageTitle>Course Catalog</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Course Catalog</h1>

    <div class="row g-3 mb-4">
        <div class="col-md-6">
            <input type="text"
                   class="form-control"
                   placeholder="Search by title, code, or instructor…"
                   @bind="SearchTerm"
                   @bind:event="oninput"
                   @bind:after="OnSearchChanged" />
        </div>
        <div class="col-md-4">
            <select class="form-select" @bind="SelectedDepartmentId" @bind:after="OnSearchChanged">
                <option value="0">All Departments</option>
                @foreach (var dept in Departments)
                {
                    <option value="@dept.Id" @key="dept.Id">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-2 d-flex align-items-center">
            <span class="text-muted">@FilteredCourses.Count result(s)</span>
        </div>
    </div>

    @if (FilteredCourses.Count == 0)
    {
        <div class="alert alert-info">No courses match your search criteria.</div>
    }
    else
    {
        <div class="row g-3">
            @foreach (var course in FilteredCourses)
            {
                <div class="col-md-6" @key="course.Id">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@course.CourseCode — @course.Title</h5>
                            <p class="card-text text-muted mb-1">@course.DepartmentName · @course.Credits credits</p>
                            <p class="card-text text-muted mb-2">@course.Instructor.Name · @course.Schedule</p>
                            <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                            <a href="/enroll?courseId=@course.Id" class="btn btn-outline-success btn-sm ms-1">Enroll</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Inject] public CatalogService Catalog { get; set; } = default!;

    [SupplyParameterFromQuery(Name = "dept")]
    public int? DeptFromQuery { get; set; }

    private string SearchTerm { get; set; } = "";
    private int SelectedDepartmentId { get; set; }
    private List<Department> Departments { get; set; } = [];
    private List<Course> FilteredCourses { get; set; } = [];

    private CancellationTokenSource? _debounceCts;

    protected override void OnInitialized()
    {
        Departments = Catalog.GetDepartments();

        if (DeptFromQuery.HasValue)
        {
            SelectedDepartmentId = DeptFromQuery.Value;
        }

        ApplyFilter();
    }

    private async Task OnSearchChanged()
    {
        _debounceCts?.Cancel();
        _debounceCts = new CancellationTokenSource();
        var token = _debounceCts.Token;

        try
        {
            await Task.Delay(250, token);
            ApplyFilter();
        }
        catch (TaskCanceledException)
        {
            // Debounce cancelled — newer input arrived
        }
    }

    private void ApplyFilter()
    {
        var deptId = SelectedDepartmentId > 0 ? SelectedDepartmentId : (int?)null;
        FilteredCourses = Catalog.SearchCourses(SearchTerm, deptId);
    }

    public void Dispose()
    {
        _debounceCts?.Cancel();
        _debounceCts?.Dispose();
    }
}

