@page "/enroll"
@using CourseCatalog.Models
@using CourseCatalog.Services

<PageTitle>Enrollment Request</PageTitle>

<div class="container py-4" style="max-width: 640px;">
    <h1 class="mb-4">Enrollment Request</h1>

    <EditForm Model="Model" method="post" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
        <DataAnnotationsValidator />
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
            <ValidationMessage For="() => Model.StudentName" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" />
            <ValidationMessage For="() => Model.StudentId" />
        </div>

        <div class="mb-3">
            <label for="courseSelect" class="form-label">Course</label>
            <InputSelect id="courseSelect" class="form-select" @bind-Value="Model.CourseId">
                <option value="0">— Select a course —</option>
                @foreach (var course in AllCourses)
                {
                    <option value="@course.Id" @key="course.Id">@course.CourseCode — @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Request</button>
        <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
    </EditForm>
</div>

@code {
    [Inject] public CatalogService Catalog { get; set; } = default!;
    [Inject] public NavigationManager Nav { get; set; } = default!;

    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    private List<Course> AllCourses { get; set; } = [];

    protected override void OnInitialized()
    {
        AllCourses = Catalog.GetAllCourses();

        if (PreselectedCourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = PreselectedCourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(Model.CourseId);
        Nav.NavigateTo($"/enroll/confirmation?name={Uri.EscapeDataString(Model.StudentName)}&course={Uri.EscapeDataString(course?.Title ?? "Unknown")}");
    }
}

@page "/enroll/confirmation"

